CREATE SCHEMA IF NOT EXISTS noor_discovery; REVOKE ALL ON SCHEMA noor_discovery FROM PUBLIC; GRANT USAGE ON SCHEMA noor_discovery TO anon,authenticated; ALTER FUNCTION private.noor_find_institutions(text) SET SCHEMA noor_discovery; CREATE OR REPLACE FUNCTION public.noor_find_institutions(p_search text) RETURNS TABLE(id uuid,name text,institution_type text,slug text) LANGUAGE sql STABLE SET search_path='' AS $$ SELECT * FROM noor_discovery.noor_find_institutions(p_search); $$;
